//! Hermetic Typst compilation environment.
//!
//! `DappleWorld` deliberately provides *nothing* beyond what a render request
//! carries: the generated main source, the twelve embedded brand font faces,
//! a virtual-file map for byte assets (cover image, logo SVGs), and a
//! deterministic date. There is no filesystem access, no network, and no
//! package resolution — a `#import "@preview/…"` can never resolve, which is
//! fine because every line of Typst source is machine-generated by this crate.
//! Determinism matters: the same request must produce byte-identical PDFs
//! across deployments (content-hash dedup upstream relies on stable output).

use std::collections::HashMap;

use typst::diag::{FileError, FileResult};
use typst::foundations::{Bytes, Datetime};
use typst::syntax::{FileId, RootedPath, Source, VirtualPath, VirtualRoot};
use typst::text::{Font, FontBook};
use typst::utils::LazyHash;
use typst::{Library, LibraryExt};

/// The 12 embedded font faces: DejaVu Serif (body), Liberation Sans
/// (headings), DejaVu Sans Mono (code) — 4 faces each. Same vendored TTFs the
/// genpdf pipeline shipped; licenses in `assets/fonts/`.
const FONT_BYTES: &[&[u8]] = &[
    include_bytes!("../../assets/fonts/DejaVuSerif.ttf"),
    include_bytes!("../../assets/fonts/DejaVuSerif-Bold.ttf"),
    include_bytes!("../../assets/fonts/DejaVuSerif-Italic.ttf"),
    include_bytes!("../../assets/fonts/DejaVuSerif-BoldItalic.ttf"),
    include_bytes!("../../assets/fonts/LiberationSans-Regular.ttf"),
    include_bytes!("../../assets/fonts/LiberationSans-Bold.ttf"),
    include_bytes!("../../assets/fonts/LiberationSans-Italic.ttf"),
    include_bytes!("../../assets/fonts/LiberationSans-BoldItalic.ttf"),
    include_bytes!("../../assets/fonts/DejaVuSansMono.ttf"),
    include_bytes!("../../assets/fonts/DejaVuSansMono-Bold.ttf"),
    include_bytes!("../../assets/fonts/DejaVuSansMono-Oblique.ttf"),
    include_bytes!("../../assets/fonts/DejaVuSansMono-BoldOblique.ttf"),
];

/// A named virtual file made available to the generated source (e.g.
/// `#image("/cover-image.png")`). Names are rooted at the virtual project root.
pub type VirtualAsset = (String, Vec<u8>);

pub struct DappleWorld {
    library: LazyHash<Library>,
    book: LazyHash<FontBook>,
    fonts: Vec<Font>,
    main: Source,
    files: HashMap<FileId, Bytes>,
    today: Option<Datetime>,
}

/// Build a project-rooted `FileId` for a virtual path like `/main.typ`.
fn project_file_id(path: &str) -> Option<FileId> {
    let vpath = VirtualPath::new(path).ok()?;
    Some(FileId::new(RootedPath::new(VirtualRoot::Project, vpath)))
}

impl DappleWorld {
    /// Build a world holding `main_source` plus `assets` as virtual files.
    ///
    /// `date` is a lenient `YYYY-MM-DD` prefix (the request's preformatted
    /// display date is accepted as-is); unparseable or absent dates mean
    /// `datetime.today()` is simply unavailable in the source — the system
    /// clock is NEVER consulted.
    pub fn new(main_source: String, assets: Vec<VirtualAsset>, date: Option<&str>) -> Self {
        let fonts: Vec<Font> = FONT_BYTES
            .iter()
            .flat_map(|bytes| Font::iter(Bytes::new(*bytes)))
            .collect();
        let book = FontBook::from_fonts(&fonts);

        let main_id =
            project_file_id("/main.typ").expect("static main path is a valid virtual path");
        let files = assets
            .into_iter()
            .filter_map(|(name, bytes)| {
                let path = format!("/{}", name.trim_start_matches('/'));
                match project_file_id(&path) {
                    Some(id) => Some((id, Bytes::new(bytes))),
                    None => {
                        log::warn!("skipping virtual asset with invalid path: {name}");
                        None
                    }
                }
            })
            .collect();

        Self {
            library: LazyHash::new(Library::default()),
            book: LazyHash::new(book),
            fonts,
            main: Source::new(main_id, main_source),
            files,
            today: date.and_then(parse_iso_date_prefix),
        }
    }

    /// The main source, for mapping diagnostic spans back to generated lines.
    pub fn main_source(&self) -> &Source {
        &self.main
    }
}

impl typst::World for DappleWorld {
    fn library(&self) -> &LazyHash<Library> {
        &self.library
    }

    fn book(&self) -> &LazyHash<FontBook> {
        &self.book
    }

    fn main(&self) -> FileId {
        self.main.id()
    }

    fn source(&self, id: FileId) -> FileResult<Source> {
        if id == self.main.id() {
            Ok(self.main.clone())
        } else {
            Err(FileError::NotFound(id.vpath().get_without_slash().into()))
        }
    }

    fn file(&self, id: FileId) -> FileResult<Bytes> {
        self.files
            .get(&id)
            .cloned()
            .ok_or_else(|| FileError::NotFound(id.vpath().get_without_slash().into()))
    }

    fn font(&self, index: usize) -> Option<Font> {
        self.fonts.get(index).cloned()
    }

    fn today(&self, _offset: Option<typst::foundations::Duration>) -> Option<Datetime> {
        self.today
    }
}

/// Parse a leading `YYYY-MM-DD` from a display date string.
fn parse_iso_date_prefix(s: &str) -> Option<Datetime> {
    let s = s.trim();
    let bytes = s.as_bytes();
    if bytes.len() < 10 || bytes[4] != b'-' || bytes[7] != b'-' {
        return None;
    }
    let year: i32 = s.get(0..4)?.parse().ok()?;
    let month: u8 = s.get(5..7)?.parse().ok()?;
    let day: u8 = s.get(8..10)?.parse().ok()?;
    Datetime::from_ymd(year, month, day)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_fonts_load_and_cover_three_families() {
        let world = DappleWorld::new(String::new(), vec![], None);
        assert!(
            world.fonts.len() >= 12,
            "expected all 12 faces, got {}",
            world.fonts.len()
        );
        for family in [
            crate::theme::FONT_SERIF,
            crate::theme::FONT_SANS,
            crate::theme::FONT_MONO,
        ] {
            assert!(
                world
                    .book
                    .select_family(&family.to_lowercase())
                    .next()
                    .is_some(),
                "family missing from font book: {family}"
            );
        }
    }

    #[test]
    fn date_parsing_is_lenient_prefix_only() {
        assert!(parse_iso_date_prefix("2026-07-25").is_some());
        assert!(parse_iso_date_prefix("2026-07-25 (Q2 close)").is_some());
        assert!(parse_iso_date_prefix("July 25, 2026").is_none());
        assert!(parse_iso_date_prefix("").is_none());
    }
}
